set -euo pipefail
upload_dir=$(getent passwd "$SUDO_USER" | cut -d: -f6)
cd /opt/news-flow/current
/opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import assert from 'node:assert/strict';import {createRequire} from 'node:module';import {createHash} from 'node:crypto';import {DatabaseSync} from 'node:sqlite';import {cnnLitePublicAccessProofMatches} from './src/web/newsCnnLite.mjs';const root='/var/lib/news-flow/qc-recover25-20261122',require=createRequire('/opt/news-flow/current/package.json'),dotenv=require('dotenv'),ES=require('elasticsearch'),env=dotenv.parse(fs.readFileSync('/etc/news-flow/news.env')),es=new ES.Client({host:env.ES5_HOST,apiVersion:'5.6',log:[],maxRetries:0,requestTimeout:15000}),db=new DatabaseSync('/var/lib/news-flow/news-flow-runtime/write.sqlite',{readOnly:true}),apply=JSON.parse(fs.readFileSync(root+'/cnn-apply-result.json')),from=Date.parse(apply.at),rows=db.prepare("SELECT * FROM import_receipts WHERE imported_at>=? AND url LIKE '%cnn.com/%' ORDER BY imported_at,id").all(from),events=db.prepare("SELECT details FROM events WHERE site='edition.cnn.com' AND kind='verified' AND at>=?").all(from),byId=new Map(events.map(e=>{const v=JSON.parse(e.details);return [v.id,v];})),r={at:new Date().toISOString(),rows:[]};try{const info=await es.info(),proof=JSON.parse(fs.readFileSync('/etc/news-flow/identity-proof.json')).summary;assert(proof.verified&&info.version.number.startsWith('5.6.')&&createHash('sha256').update(info.cluster_uuid).digest('hex')===proof.clusterFingerprint);for(let i=0;i<rows.length;i+=50){const batch=rows.slice(i,i+50),response=await es.mget({body:{docs:batch.map(s=>({_index:s.es_index,_type:s.es_type,_id:s.es_id}))}});for(let j=0;j<batch.length;j++){const row=batch[j],doc=response.docs[j],event=byId.get(row.id),o={url:row.url,id:row.id,receiptStatus:row.status,found:doc.found===true,proofMatched:doc.found===true&&cnnLitePublicAccessProofMatches(doc._source,event?.publicAccessProof),descriptionPresent:!!doc._source?.description,publishedDate:doc._source?.publishedDate};r.rows.push(o);}}r.verified=r.rows.length>=5&&r.rows.every(p=>p.found&&p.proofMatched&&p.descriptionPresent);assert(r.verified);fs.writeFileSync(root+'/all-cnn-es-readback.json',JSON.stringify(r,null,2));console.log(JSON.stringify({records:r.rows.length,allProofsMatched:r.verified,created:r.rows.filter(p=>p.receiptStatus==='created').length,at:r.at}));}finally{db.close();es.close();}
NODE
install -o "$SUDO_USER" -m 0600 /var/lib/news-flow/qc-recover25-20261122/all-cnn-es-readback.json "$upload_dir/.qc-recover25-all-cnn-es-readback.json"
